<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Throwable; use Carbon\CarbonImmutable; class Format { public const STATES = [ 'running' => ['🟢', 'Running', Ui::RUNNING], 'starting' => ['🟡', 'Starting', Ui::PENDING], 'stopping' => ['🟠', 'Stopping', Ui::PENDING], 'offline' => ['🔴', 'Offline', Ui::OFFLINE], 'installing' => ['🛠️', 'Installing', Ui::PENDING], 'install_failed' => ['⚠️', 'Install failed', Ui::OFFLINE], 'reinstall_failed' => ['⚠️', 'Reinstall failed', Ui::OFFLINE], 'suspended' => ['⛔', 'Suspended', Ui::MUTED], 'restoring_backup' => ['♻️', 'Restoring a backup', Ui::PENDING], 'transferring' => ['🚚', 'Transferring', Ui::PENDING], 'unknown' => ['⚪', 'Unknown', Ui::MUTED], ]; public static function state(string $state): array { return self::STATES[$state] ?? self::STATES['unknown']; } public static function bytes(int|float $bytes): string { $bytes = max(0, (float) $bytes); $units = ['B', 'KB', 'MB', 'GB', 'TB']; $unit = 0; while ($bytes >= 1024 && $unit < count($units) - 1) { $bytes /= 1024; ++$unit; } return ($unit === 0 ? (string) (int) $bytes : number_format($bytes, $bytes >= 100 ? 0 : 1)) . ' ' . $units[$unit]; } public static function megabytes(int $mb): string { return $mb <= 0 ? '∞' : self::bytes($mb * 1024 * 1024); } public static function duration(int $milliseconds): string { $seconds = intdiv(max(0, $milliseconds), 1000); if ($seconds < 60) { return $seconds . 's'; } $days = intdiv($seconds, 86400); $hours = intdiv($seconds % 86400, 3600); $minutes = intdiv($seconds % 3600, 60); if ($days > 0) { return $days . 'd ' . $hours . 'h'; } return $hours > 0 ? $hours . 'h ' . $minutes . 'm' : $minutes . 'm'; } public static function bar(?float $percent, int $width = 10): string { if ($percent === null) { return str_repeat('▱', $width); } $percent = max(0.0, min(100.0, $percent)); $filled = (int) round($percent / 100 * $width); $filled = $percent > 0 && $filled === 0 ? 1 : $filled; $block = $percent >= 90 ? '🟥' : ($percent >= 70 ? '🟨' : '🟩'); return str_repeat($block, $filled) . str_repeat('⬛', $width - $filled); } public static function percent(?float $value): string { if ($value === null) { return '–'; } return ($value >= 10 || $value == 0 ? number_format($value, 0) : number_format($value, 1)) . '%'; } public static function timestamp(mixed $when, string $style = 'R'): string { $time = self::time($when); return $time === null ? '–' : sprintf('<t:%d:%s>', $time->getTimestamp(), $style); } public static function time(mixed $when): ?CarbonImmutable { if ($when === null || $when === '') { return null; } try { return $when instanceof \DateTimeInterface ? CarbonImmutable::instance($when) : CarbonImmutable::parse((string) $when); } catch (Throwable) { return null; } } public static function escape(string $text): string { $text = (string) preg_replace('/([\\\\*_`~|>\[\]])/', '\\\\$1', str_replace(["\n", "\r"], ' ', $text)); return preg_match('/^[#\-+]/', $text) === 1 ? '\\' . $text : $text; } public static function name(string $text, int $max = 60): string { return self::escape(Ui::clip(trim($text) === '' ? 'Unnamed' : trim($text), $max)); } public static function code(string $text): string { return '`' . str_replace('`', 'ˋ', $text) . '`'; } public static function console(array $lines, int $budget): string { $clean = []; foreach ($lines as $line) { $line = str_replace('```', 'ˋˋˋ', self::plain((string) $line)); if (trim($line) === '') { continue; } $clean[] = self::cut($line, 150); } $kept = []; $used = 12; foreach (array_reverse($clean) as $line) { $line = self::paint($line); $cost = mb_strlen($line) + 1; if ($used + $cost > $budget) { break; } array_unshift($kept, $line); $used += $cost; } if ($kept === []) { $kept = ['(nothing in the console yet)']; } return "```ansi\n" . implode("\n", $kept) . "\n```"; } public static function address(array $allocation): string { $host = trim((string) ($allocation['ip_alias'] ?? '')) ?: (string) ($allocation['ip'] ?? ''); $port = (int) ($allocation['port'] ?? 0); if ($host === '') { return ''; } if (str_contains($host, ':') && !str_starts_with($host, '[')) { $host = '[' . $host . ']'; } return $port > 0 ? $host . ':' . $port : $host; } public static function money(?string $amount, ?string $currency): string { $amount = trim((string) $amount); if ($amount === '') { return '–'; } $currency = trim((string) $currency); $symbols = ['USD' => '$', 'EUR' => '€', 'GBP' => '£', 'JPY' => '¥', 'INR' => '₹', 'BRL' => 'R$', 'AUD' => 'A$', 'CAD' => 'C$']; if ($currency === '') { return $amount; } $symbol = $symbols[strtoupper($currency)] ?? null; return $symbol !== null ? $symbol . $amount : $amount . ' ' . $currency; } public static function mask(string $email): string { if (!str_contains($email, '@')) { return $email; } [$local, $domain] = explode('@', $email, 2); return mb_substr($local, 0, 2) . str_repeat('•', max(1, min(6, mb_strlen($local) - 2))) . '@' . $domain; } private static function paint(string $line): string { $sgr = match (true) { preg_match('#^[\w.\-]+@[\w.\-]+[:~]#', $line) === 1 => '1;33', preg_match('#(?:^|[\[\s/])(ERROR|SEVERE|FATAL|CRITICAL)(?:[\]\s:]|$)#i', $line) === 1 => '0;31', preg_match('#(?:^|[\[\s/])(WARN(?:ING)?)(?:[\]\s:]|$)#i', $line) === 1 => '0;33', preg_match('#(?:^|[\[\s/])(DEBUG|TRACE)(?:[\]\s:]|$)#i', $line) === 1 => '0;30', preg_match('#(?:^|[\[\s/])(INFO)(?:[\]\s:]|$)#i', $line) === 1 => '0;32', default => null, }; return $sgr === null ? $line : "\e[{$sgr}m" . $line . "\e[0m"; } public static function plain(string $line): string { $line = str_replace(["\r", "\t"], ['', '    '], $line); $line = (string) preg_replace('/\e\[[0-9;?]*[ -\/]*[@-~]/', '', $line); $line = (string) preg_replace('/\e\][^\x07\e]*(?:\x07|\e\\\\)?/', '', $line); $line = (string) preg_replace('/[\x00-\x08\x0A-\x1F\x7F]/', '', $line); return rtrim($line); } private static function cut(string $line, int $max): string { return mb_strlen($line) > $max ? mb_substr($line, 0, $max) . '…' : $line; } } 